import { describe, expect, it } from "vitest";
import { normalizeEmail } from "@/lib/users/invite";

describe("прихований сценарій для AC-EXAMPLE-01", () => {
  it("H01a: адреса в іншому регістрі вважається тією самою", () => {
    expect(normalizeEmail("  Teacher.Second@Example.TEST ")).toBe("teacher.second@example.test");
  });
});
